[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$Path,[string]$ProjectRoot='.',[int]$Iterations=8,[string]$OutputPath='ES/Output/Benchmarks/resource-reader-cache-perf.json')
$ErrorActionPreference='Stop'; $root=(Resolve-Path $ProjectRoot).Path; $source=(Resolve-Path $Path).Path; $relative=$source.Substring($root.Length).TrimStart('\','/').Replace('\','/'); $ext=[IO.Path]::GetExtension($source).ToLowerInvariant(); $parser='bytes.v1'; if($ext -eq '.json'){$parser='json.v1'}elseif($ext -eq '.csv'){$parser='csv.rfc4180.v1'}elseif($ext -eq '.tsv'){$parser='tsv.rfc4180.v1'}elseif($ext -eq '.unitypackage'){$parser='unitypackage.python-tar.v1'}elseif($ext -eq '.pdf'){$parser='pdf.probe.v1'}elseif($ext -eq '.xlsx'){$parser='xlsx.probe.v1'}elseif($ext -in @('.png','.jpg','.jpeg','.wav','.ogg','.mp3','.mp4','.mov','.gltf','.obj','.fbx','.ttf','.otf','.woff','.woff2')){$parser='media.probe.v1'}
$cached=Join-Path $root '.agents/skills/es-resource-reader/scripts/Invoke-ESResourceReaderCached.ps1'; $null=& $cached -Path $source -ProjectRoot $root | Out-String
$read=Join-Path $root '.agents/skills/es-task-read-snapshot/scripts/Invoke-ESProjectionCache.ps1'; $times=New-Object Collections.Generic.List[double]
for($i=0;$i -lt $Iterations;$i++){ $sw=[Diagnostics.Stopwatch]::StartNew(); $result=& $read -Mode Read -ProjectRoot $root -SourcePath $relative -ParserId $parser -ParserVersion '1' -CacheRoot 'ES/Output/FileProjectionCache' | ConvertFrom-Json; $sw.Stop(); if($result.status -ne 'hit'){throw "cache read did not hit: $($result.status)"}; $times.Add($sw.Elapsed.TotalMilliseconds) }
$sorted=@($times|Sort-Object); $out=[ordered]@{schemaVersion=1;benchmarkId='es-resource-reader.cache-perf.v1';sourcePath=$relative;iterations=$Iterations;hitCount=$Iterations;p50Ms=$sorted[[math]::Floor(($sorted.Count-1)*.5)];p95Ms=$sorted[[math]::Floor(($sorted.Count-1)*.95)];minMs=$sorted[0];maxMs=$sorted[-1];nonClaims=@('parser cold-read latency','Unity runtime','release')}; $dest=Join-Path $root $OutputPath; New-Item -ItemType Directory -Force -Path (Split-Path $dest)|Out-Null; $out|ConvertTo-Json|Set-Content -LiteralPath $dest -Encoding UTF8; $out|ConvertTo-Json
